"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request

WINDOW_LIMIT = 1000
REQUEST_TIMEOUT = 10


def _retry_after_seconds(err):
    value = err.headers.get("Retry-After")
    try:
        return max(0.0, float(value))
    except (TypeError, ValueError):
        return 1.0


def _fetch_window(endpoint, cursor):
    """Fetch one window, retrying 429s. Returns (data, restart_from_start)."""
    params = {"limit": str(WINDOW_LIMIT)}
    if cursor is not None:
        params["cursor"] = cursor
    url = f"{endpoint}?{urllib.parse.urlencode(params)}"
    while True:
        try:
            with urllib.request.urlopen(url, timeout=REQUEST_TIMEOUT) as resp:
                return json.load(resp), False
        except urllib.error.HTTPError as err:
            if err.code == 429:
                time.sleep(_retry_after_seconds(err))
                continue
            if err.code == 400:
                try:
                    body = json.load(err)
                except (ValueError, OSError):
                    body = {}
                if body.get("error") == "invalid_cursor" and cursor is not None:
                    return None, True
            raise


def fetch_payouts(base_url):
    endpoint = f"{base_url}/v2/payouts"
    seen = set()
    payouts = []
    cursor = None

    while True:
        data, restart = _fetch_window(endpoint, cursor)
        if restart:
            # The cursor was rejected; restart the export from the beginning.
            # Any payouts already collected are kept and deduplicated by id.
            cursor = None
            continue

        for payout in data["payouts"]:
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                payouts.append(payout)

        if data["drained"]:
            break
        cursor = data["cursor"]

    return payouts


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

